// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _test(uint256 _depositAmount) internal {
        _depositAmount = bound(_depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_depositAmount == c.MinDeposit());
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        try c.Deposit{value: _depositAmount}() {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue(balAfter > balBefore);
    }

    function testFuzz_test(uint256 _depositAmount) public {
        _test(_depositAmount);
    }

    receive() external payable {}
}
